files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 20px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  border-radius: 12px;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 0 var(--border);
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 8px;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.subtitle {
  color: var(--muted);
  margin: 0 0 24px;
  font-size: 0.95rem;
}

.dials {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-bottom: 24px;
}

.dial {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.arrow {
  width: 48px;
  height: 48px;
  font-size: 1.2rem;
  background: var(--border);
  color: var(--text);
  border: 2px solid var(--accent);
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.arrow:hover {
  background: var(--accent);
}

.arrow:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.arrow:active {
  transform: translateY(2px);
  background: var(--accent);
}

.digit {
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  font-weight: bold;
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 8px;
  font-family: 'Courier New', monospace;
}

.open-btn {
  width: 100%;
  padding: 14px;
  font-size: 1.1rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 2px;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  margin-bottom: 16px;
}

.open-btn:hover {
  background: #c7364f;
}

.open-btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.open-btn:active {
  transform: translateY(2px);
}

.open-btn:disabled {
  background: var(--border);
  color: var(--muted);
  cursor: not-allowed;
  transform: none;
}

.status {
  min-height: 1.5em;
  margin: 0 0 8px;
  font-weight: bold;
}

.status.success {
  color: #4ade80;
}

.status.error {
  color: var(--accent);
}

.attempts {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .dials {
    gap: 8px;
  }
  .arrow {
    width: 40px;
    height: 40px;
  }
  .digit {
    width: 52px;
    height: 52px;
    font-size: 1.6rem;
  }
}

const dials = [0, 0, 0];
const target = [3, 7, 2];
let attempts = 0;
let locked = false;

const digitEls = [
  document.getElementById('digit-0'),
  document.getElementById('digit-1'),
  document.getElementById('digit-2')
];
const openBtn = document.getElementById('open-btn');
const statusEl = document.getElementById('status');
const attemptCountEl = document.getElementById('attempt-count');

function updateDisplay() {
  dials.forEach((val, i) => {
    digitEls[i].textContent = val;
  });
}

function changeDial(index, delta) {
  if (locked) return;
  dials[index] = (dials[index] + delta + 10) % 10;
  updateDisplay();
  statusEl.textContent = '';
  statusEl.className = 'status';
}

function checkCombination() {
  if (locked) return;
  const match = dials.every((val, i) => val === target[i]);
  if (match) {
    locked = true;
    statusEl.textContent = '🔓 Unlocked! The lock is open.';
    statusEl.className = 'status success';
    openBtn.disabled = true;
    document.querySelectorAll('.arrow').forEach(btn => btn.disabled = true);
  } else {
    attempts++;
    attemptCountEl.textContent = attempts;
    statusEl.textContent = '❌ Incorrect combination. Try again.';
    statusEl.className = 'status error';
  }
}

// Attach arrow button listeners
document.querySelectorAll('.dial').forEach(dial => {
  const index = parseInt(dial.dataset.index, 10);
  const up = dial.querySelector('.up');
  const down = dial.querySelector('.down');
  up.addEventListener('click', () => changeDial(index, 1));
  down.addEventListener('click', () => changeDial(index, -1));
});

openBtn.addEventListener('click', checkCombination);

// Initial render
updateDisplay();
